<script setup>
import {computed,ref,watch} from 'vue';
const props=defineProps({rows:{type:Array,default:()=>[]},columns:{type:Array,required:true},pageSize:{type:Number,default:30},searchable:{type:Boolean,default:true},total:{type:Boolean,default:true}});
const emit=defineEmits(['open']);const query=ref(''),sort=ref(''),direction=ref(1),page=ref(1);
const value=(row,c)=>c.v?c.v(row):row[c.k||c.key];
const filtered=computed(()=>props.rows.filter(row=>!query.value||props.columns.some(c=>c.search!==false&&String(value(row,c)??'').toLowerCase().includes(query.value.toLowerCase()))).slice().sort((a,b)=>{if(!sort.value)return 0;const c=props.columns.find(c=>(c.k||c.key)===sort.value),av=value(a,c),bv=value(b,c);return direction.value*(typeof av==='number'&&typeof bv==='number'?av-bv:String(av??'').localeCompare(String(bv??''),undefined,{numeric:true}));}));
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/props.pageSize))),visible=computed(()=>filtered.value.slice((page.value-1)*props.pageSize,page.value*props.pageSize));
watch([query,()=>props.rows],()=>page.value=1);
function order(c){const key=c.k||c.key;if(sort.value===key)direction.value*=-1;else{sort.value=key;direction.value=1;}}
const format=(v,c)=>v==null?'—':c.t==='amt'?'₹'+Number(v).toLocaleString('en-IN',{maximumFractionDigits:2}):c.t==='pct'?Number(v).toFixed(1)+'%':Array.isArray(v)?v.join(', '):String(v);
const sum=c=>c.sumFn?c.sumFn(filtered.value):filtered.value.reduce((n,row)=>n+(Number(value(row,c))||0),0);
</script>
<template><div class="esr-card native-table"><div v-if="searchable" class="esr-tblbar"><input v-model="query" type="search" placeholder="Search this table…" aria-label="Search this table"><span>{{filtered.length}} records</span></div><div class="esr-tblbox cl-table-wrap tw"><table class="esr-table tt"><thead><tr><th v-for="c in columns" :key="c.k||c.key" scope="col" @click="order(c)"><button type="button">{{c.l||c.label}}{{sort===(c.k||c.key)?direction===1?' ↑':' ↓':''}}</button></th></tr></thead><tbody><tr v-for="(row,i) in visible" :key="row.id||row.key||row.name||i" @dblclick="emit('open',row)"><td v-for="c in columns" :key="c.k||c.key" :data-label="c.l||c.label" :class="typeof c.cls==='function'?c.cls(row):c.cls"><slot name="cell" :row="row" :column="c" :value="value(row,c)">{{format(value(row,c),c)}}</slot></td></tr><tr v-if="!visible.length"><td :colspan="columns.length" class="esr-empty">No matching records.</td></tr></tbody><tfoot v-if="total&&filtered.length"><tr><td v-for="(c,i) in columns" :key="c.k||c.key">{{i===0?'TOTAL':c.sum||c.sumFn?format(sum(c),c):''}}</td></tr></tfoot></table></div><nav v-if="pages>1" class="esr-pager"><button :disabled="page===1" @click="page--">Previous</button><span>{{page}} / {{pages}}</span><button :disabled="page===pages" @click="page++">Next</button></nav></div></template>
<style scoped>.native-table{min-width:0}table{width:100%;border-collapse:collapse}th,td{padding:9px;border-bottom:1px solid #dce9de;text-align:left}th button{background:none;border:0;color:inherit;font:inherit;cursor:pointer}.cl-table-wrap{overflow:auto;max-width:100%}.esr-tblbar,.esr-pager{display:flex;align-items:center;gap:12px;padding:10px}tfoot{font-weight:bold}.esr-empty{text-align:center;padding:24px}</style>
